/// A grid of texts to import.
class TableData {
  /// The number of columns.
  final int xs;

  /// The cells row by row: whole rows, at least one cell.
  final List<EntryData> cells;

  const TableData({required this.xs, required this.cells});

  @override
  int get hashCode => xs.hashCode ^ cells.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TableData &&
          runtimeType == other.runtimeType &&
          xs == other.xs &&
          cells == other.cells;
}

/// Vertical alignment of a cell's content.
enum VertAlign {
  /// Decided by the draw style.
  auto,

  /// Top.
  top,

  /// Middle.
  middle,

  /// Bottom.
  bottom,
}
